package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Nothing is silently replaced by a default: a missing file, an unknown key or a value that does not
 * parse makes the load fail, and every problem found is reported together in one {@link ConfigException}.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();
        unknownKeys(properties, problems);
        java.net.URI upstream = uri(properties, "upstream.url", problems);
        String apiToken = required(properties, "api.token", problems);
        int workerThreads = intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, "request.timeout", problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", problems);

        if (!problems.isEmpty()) {
            StringBuilder message = new StringBuilder();
            for (String problem : problems) {
                message.append("  - ").append(problem).append('\n');
            }
            throw new ConfigException(message.toString().stripTrailing());
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("config file not found: " + file.toAbsolutePath());
        } catch (IOException e) {
            throw new ConfigException("cannot read config file " + file.toAbsolutePath() + ": " + e.getMessage());
        } catch (IllegalArgumentException e) {
            throw new ConfigException("config file " + file.toAbsolutePath() + " is malformed: " + e.getMessage());
        }
        return properties;
    }

    private static void unknownKeys(Properties properties, List<String> problems) {
        properties.stringPropertyNames().stream()
                .filter(key -> !KNOWN_KEYS.contains(key))
                .sorted()
                .forEach(key -> problems.add(key + ": unknown setting, check the spelling"));
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + ": is required");
            return null;
        }
        return value.trim();
    }

    private static URI uri(Properties properties, String key, List<String> problems) {
        String raw = required(properties, key, problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            if (uri.isAbsolute() && uri.getHost() != null) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add(key + ": must be an absolute URL such as https://host/path, got '" + raw + "'");
        return null;
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String value = raw.trim();
        try {
            int parsed = Integer.parseInt(value);
            if (parsed >= minimum) {
                return parsed;
            }
            problems.add(key + ": must be at least " + minimum + ", got '" + value + "'");
        } catch (NumberFormatException e) {
            problems.add(key + ": must be a whole number, got '" + value + "'");
        }
        return defaultValue;
    }

    private static Duration duration(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        String value = raw.trim();
        Matcher matcher = DURATION.matcher(value);
        if (matcher.matches()) {
            try {
                long amount = Long.parseLong(matcher.group(1));
                return switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
            } catch (ArithmeticException | NumberFormatException e) {
                // out of range, reported below
            }
        }
        problems.add(key + ": must be a whole number followed by ms, s or m, such as 30s, got '" + value + "'");
        return DEFAULT_REQUEST_TIMEOUT;
    }

    private static boolean bool(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (value.equalsIgnoreCase("true")) {
            return true;
        }
        if (!value.equalsIgnoreCase("false")) {
            problems.add(key + ": must be true or false, got '" + value + "'");
        }
        return false;
    }
}

